---刷新当前信息
---@param levelId string @ 关卡id
---@param teamIndex integer @ 队伍位置
---@param chooseCardStatu integer @ 委托状态
---@param entrustId string @ 委托队列id
function UIFightChooseCardsLeftNode:SetCurLevelId(levelId, teamIndex, chooseCardStatu, entrustId)
    self.curLevelId = levelId
    self._teamIndex = teamIndex
    self.chooseCardStatu = checkNumber(chooseCardStatu)
    self._entrustId = checkString(entrustId)

    local curLevelType = GoodsUtils.GetIdType(self.curLevelId, Constants.IDArea.Quests)     --关卡类型
    if curLevelType == Constants.IDType.QuestWorldBoss
    or curLevelType == Constants.IDType.QuestLadderStruggle
    or curLevelType == Constants.IDType.QuestLadderStruggleSingle
    or self.curLevelId == Constants.SpecialQuestId.FriendPVPId then
        KTool.SetActive(self.LevelUpButton, false)
    end
end

---刷新信息面板
---@param cardData CardDojo @ 卡牌信息
---@param isShowEquip boolean @ 是否显示装备
function UIFightChooseCardsLeftNode:RefreshLeftInfo(cardData, isShowEquip)
    local curLevelType = GoodsUtils.GetIdType(self.curLevelId, Constants.IDArea.Quests)     --关卡类型
    self.cardData = cardData
    if not isNull(self.cardData) then
        ---@type CardProgressionEntity
        local entity = nil
        if curLevelType == Constants.IDType.QuestPatrolMaze then
            local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
            local patrolMazeComp  = PatrolMazeUtils.GetComp()
            ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
            local mazeAreaDojo    = self._patrolMaze.areaDojo
            local mazeCardDojo    = mazeAreaDojo:GetMazeCard(cardData.id)
            entity = CardProgressionUtils.GenerateEntityByRobot(cardData)
            entity:FillPureCard(true)
            if mazeCardDojo.isAssist then
                local assistVo = PatrolMazeUtils.GetAssistCardVo(mazeCardDojo.assistId)
                entity:FillAdditionMap(assistVo.additionMap)
            end
        elseif curLevelType == Constants.IDType.QuestPatrolMazeInit then
            entity = CardProgressionUtils.GenerateEntityByRobot(cardData)
            entity:FillPureCard(true)
        elseif curLevelType == Constants.IDType.Fairyland then
            entity = CardProgressionUtils.GenerateEntityByRobot(cardData)
            entity.isIgnoreGlobal = true
        else
            entity = CardProgressionUtils.GenerateEntity(cardData, cardData.isAssistant == Constants.MazeRole.AssistRole)
        end
        KTool.SetActive(self.CardInfo, true)
        KTool.SetActive(self.NoSelect, false)
        KTool.SetActive(self.LevelUpButton, checkNumber(self.cardData.isAssistant) == 0)
        CfUtils.SetActive(self.LevelUpButton, not GameUtils.IsInAnnihilation())
        self:ReFreshLeftTop(entity)
        self:RefreshItemAttribute(entity)
        self:FillEquips(entity)
        self:FillSkills(entity)
    else
        KTool.SetActive(self.CardInfo.gameObject, false)
        KTool.SetActive(self.NoSelect, true)
    end

    if curLevelType == Constants.IDType.QuestMapDecryptionMap or 
       curLevelType == Constants.IDType.QuestMapDecryptionTracking
    or curLevelType == Constants.IDType.QuestLadderStruggle
    or curLevelType == Constants.IDType.QuestLadderStruggleSingle
    or self.curLevelId == Constants.SpecialQuestId.FriendPVPId then
        KTool.SetActive(self.LevelUpButton, false)
    end
end

