--绘制技能
function UIFightChooseCardsLeftNode:FillSkills(entity)
    local cardDojo = entity.cardDojo
    local cardVo = cardConfMgr:GetCardByRefId(cardDojo.cardId)
    local level = checkNumber(self.cardData.awakeningLevel)
    local showLevel = level - 1
    --self:FreshSymbolNodes(showLevel)

    local finalSkillLevel, awakeningLevel = checkNumber(cardDojo.finalSkillLevel), checkNumber(cardDojo.awakeningLevel)
    local skills = CardProgressionSkillUtils.InitSkills(cardVo, awakeningLevel, finalSkillLevel)
    
    for i, skillInfo in ipairs(skills) do
        local node = self.SkillCardGroup.transform:Find("SkillCardNode"..i)

        local env = CfUtils.GetLuaScr(node, CardProgressionConstants.EnvPath.CardProgressionSkillNode)
        if isNull(env) then return end
        env:FreshUI(skillInfo, cardVo)
        env:SetTargetNode(self.SkillCardGroup)

        --CardProgressionSkillUtils.LoadSkillDescNode(
        --    node, 
        --    {skillData = skillInfo, cardVo = cardVo}
        --)
    end

    local skillId, skillLevel = SafeUnpack(skills[4])
    local desc = CardProgressionSkillUtils.GetFullTalentDesc(cardDojo.cardId, skillId, skillLevel)
    CfUtils.FillText(self.TextDesc, desc)
end

--绘制装备
function UIFightChooseCardsLeftNode:FillEquips(entity)
    -- local entity = CardProgressionUtils.GenerateEntityByCardDojo(self.cardData)
    local equips = checkTable(entity.equipPart2Dojo)
    self.equipIdList = {}
    for i = 1, CardProgressionConstants.EquipmentNum do
        local go = self.GoodGroup:Find("Node"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.Node, self.GoodGroup)
            go.name = "Node"..i
        end

        ---@type EquipDojo
        local data = equips[i]
        local equipmentId = data == nil and 0 or checkNumber(data.equipmentId)
        local goodsGo = go.transform:Find("GoodNode")
        local emptyGo = go.transform:Find("Empty")
        CfUtils.SetActive(go.transform:Find("Empty"), equipmentId == 0)
        CfUtils.SetActive(goodsGo, equipmentId ~= 0)

        CfUtils.SetUISwitchImage(emptyGo.transform:Find("ImgIcon"), i)
        if data then
            CfUtils.RefeshGoodGo2(goodsGo, equipmentId, nil, nil, nil, function()
                if  checkNumber(equipmentId) > 0 then
                    if not GameUtils.IsInAnnihilation() then
                        GameUtils.ShowCommonGoodsTipsBoard(goodsGo, equipmentId, false)
                    else
                        GameUtils.ShowCommonTipsEquip(goodsGo, equipmentId, data.id, Constants.IDType.Equipment)
                    end
                end
            end, data.id, data)
        end
        CfUtils.SetActive(go, true)

        local key = EquipUtils.GetEquipIdKeyByPart(i)
        self.equipIdList[i] = checkNumber(self.cardData[key])
    end

    local _t = self:GetEquipmentAttrs(entity)
    local t = {}
    for k, v in pairs(_t) do
        table.insert(t, k)
    end
    for i = 1, #t do
        local go = self.Layout:Find("Node"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.BtnEquipType, self.Layout)
            go.name = "Node"..i
        end
        local data = t[i]
        CfUtils.SetActive(go, true)

        local vo = CfUtils.GetCfVo(AutoIds.IdSetting102, "EquipFilterVo", data)
        CfUtils.FillImage(go.transform:Find("ImgTypeIcon"), vo.icon)
    end
    if #t + 1 < self.Layout.childCount then
        for i = #t + 1, self.Layout.childCount do
            local go = self.Layout.transform:Find("Node"..i)
            if go then
                CfUtils.SetActive(go, false)
            end
        end
    end
end

---获取当前卡牌的装备属性加成
function UIFightChooseCardsLeftNode:GetEquipmentAttrs(entity)
    local cardDojo               = self.cardData
    --[[
    local basicAttributeDataDict = {}
    local star                   = checkNumber(cardDojo.star)
    local cardLevel              = checkNumber(cardDojo.cardLevel)
    local emptyEquipIdList = {0, 0, 0, 0, 0, 0}
    local equipIdList = self.equipIdList
    local isOwnEquip = false
    for i, v in ipairs(equipIdList) do
        if checkNumber(v) > 0 then
            isOwnEquip = true
            break
        end
    end

    local preParams = {star = star, cardLevel = cardLevel, equipIdList = emptyEquipIdList, playerEquipCoreId = 0}
    local curParams = {star = star, cardLevel = cardLevel, equipIdList = equipIdList, playerEquipCoreId = 0}
    FormulaUtils.CompareBasicAttrs(cardDojo, cardDojo, function (basicVo, emptyEquipAttr, equipAttr, index)
        local isShowAddAttr = false
        local attrNum = 0
        if isOwnEquip then
            attrNum = equipAttr - emptyEquipAttr
            isShowAddAttr = math.abs(attrNum) > 0
        end
        if isShowAddAttr then
            basicAttributeDataDict[checkInt(basicVo.refId)] = {
                curAttr = attrNum,
                name    = basicVo.name,
                icon    = basicVo.icon,
            }
        end
    end, preParams, curParams)
    ]]

    -- local entity = CardProgressionUtils.GenerateEntity(cardDojo, cardDojo.isAssistant == Constants.MazeRole.AssistRole)
    local curEquipListSuitInfo = EquipUtils.GetEquipSuitInfoByEquipDojoList(entity.equipPart2Dojo)

    return curEquipListSuitInfo
end

function UIFightChooseCardsLeftNode:GetAttributesAndCombatPower(entity, cardId, isReload)
    local t, combatEffectiveness
    if self._attributes == nil or isReload then
        ---@type CardVo
        local cardVo = cardConfMgr:GetCardByRefId(cardId)
        ---@type CatTypeVo
        local cardTypeVo = cardConfMgr:GetCatTypeVoById(cardVo.catType)
        t = {
            {order = -3, icon = CardProgressionConstants.AssetPath.Attribute, name = localize("属性"), cardAttrId = cardVo.attributeType,           viewType = CardProgressionConstants.AttrNodeType.CardAttr},
            {order = -2, icon = CardProgressionConstants.AssetPath.Race,      name = localize("阵营"), raceId = cardVo.race,                        viewType = CardProgressionConstants.AttrNodeType.Race},
            {order = -1, icon = CardProgressionConstants.AssetPath.CatType,   name = localize("血统"), desc = cardTypeVo and cardTypeVo.name or "", viewType = CardProgressionConstants.AttrNodeType.CatType},
        }
        local attribute_format = attribute_format
        combatEffectiveness = FormulaUtils.CalcCardCombatEffectiveness(entity, nil, function (vo, num, index)
            local order = vo.order
            if vo.order > 0 then
                local text = attribute_format(vo.isConversion, num)
                table.insert(t, {
                    order = order,
                    icon = vo.icon,
                    name = vo.name,
                    attrNum = text,
                    viewType = CardProgressionConstants.AttrNodeType.Single,
                })
            end
        end)
        table.sort(t, function(a, b) return a.order < b.order end)
        self._attributes = t
        self._combatEffectiveness = combatEffectiveness
    else
        t = self._attributes
        combatEffectiveness = self._combatEffectiveness
    end
    return t, combatEffectiveness
end

---刷新头部信息
---@param entity CardProgressionEntity
function UIFightChooseCardsLeftNode:ReFreshLeftTop(entity)
    local cardVo = cardConfMgr:GetCardByRefId(entity.cardId)

    CfUtils.FillText(self.LeftTop.transform:Find("CardName2"), cardVo.name)

    local vo = cardConfMgr:GetRolesVo(cardVo.characterId) 
    if vo then
        CfUtils.FillText(self.CardName, vo.name)
    end

    ---@type CardDojo
    local cardDojo = entity.cardDojo
    --local starVo = cardConfMgr:GetCardStarInfo(self.cardData.cardId, self.cardData.star)
    local maxLevel = 10--starVo.maxLevel
    local isCanUpgradeLevel = checkNumber(cardDojo.cardLevel) < maxLevel
    local isCanUpgradeStar = checkNumber(cardDojo.star) < Constants.CardMaxStar

    if (isCanUpgradeLevel or isCanUpgradeStar) then
        CfUtils.FillText(self.GradeNum, cardDojo.cardLevel)
    else
        CfUtils.FillText(self.GradeNum, "MAX")
    end

    -- local fightVal = FormulaUtils.GetCardFightingStrengthen(cardDojo)  --武力值
    
    local curLevelType = GoodsUtils.GetIdType(self.curLevelId, Constants.IDArea.Quests)     --关卡类型
    if curLevelType == Constants.IDType.QuestPatrolMaze then
        local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
        local patrolMazeComp  = PatrolMazeUtils.GetComp()
        ---@type PatrolMazeAreaDojo @ 当前所在区域dojo
        local mazeAreaDojo    = self._patrolMaze.areaDojo
        local mazeCardDojo    = mazeAreaDojo:GetMazeCard(self.cardData.id)
        self.StarLevel:SetStarNo(Constants.CardMaxStar, 0, checkNumber(mazeCardDojo.cardDojo.star))
    elseif curLevelType == Constants.IDType.QuestPatrolMazeInit then
        self.StarLevel:SetStarNo(Constants.CardMaxStar, 0, checkNumber(self.cardData.star))
    else
        local dojo = cardComponent:GetCardById(cardComponent:GetIdByCardId(cardDojo.cardId))
        if dojo then
            self.StarLevel:SetStarNo(Constants.CardMaxStar, 0, checkNumber(cardDojo.star))
        end
    end

    ---@type JobVo
    local jobVo = cardConfMgr:GetCardCareerRowByType(cardVo.career)
    self.ImgCareerIcon:LoadSprite(jobVo.largeIcon)
    CfUtils.FillImage(self.LeftTop.transform:Find("BtnCareer/ImgAttributeBg"), CardUtils.GetCardAttrIconPath(cardVo.attributeType, true))
    CfUtils.FillImage(self.LeftTop.transform:Find("BtnCamp/ImgCamp"), CardUtils.GetCardRaceIconPath(cardVo.race, true, true))
end

function UIFightChooseCardsLeftNode:OnDestroy()
    if not isNull(self.tipsBoardCo) then
        cs_coroutine.stop(self.tipsBoardCo)
        self.tipsBoardCo = nil
    end

    if not isNull(self.skillDescCo) then
        cs_coroutine.stop(self.skillDescCo)
        self.skillDescCo = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFightChooseCardsLeftNode





